package leo.modules.output.LPoutput

import leo.modules.output.LPoutput.lpDatastructures._

object LPSignature {

  abstract class lpAxioms extends lpTerm{
    def name: lpConstantTerm
    def ty: lpMlType
  }

  case object lpEm extends lpAxioms{
    //  Π x: Prop, Prf (x ∨ ¬ x)
    override def name: lpConstantTerm = lpConstantTerm("em")
    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"),lpOtype.lift2Meta)),lpOlUntypedBinaryConnectiveTerm(lpOr,lpOlConstantTerm("x"),lpOlUnaryConnectiveTerm(lpNot,lpOlConstantTerm("x"))).prf)
    override def pretty: String = lpDeclaration(lpEm.name,Seq.empty,lpEm.ty).pretty
  }

  case object lpDne extends lpAxioms {
    // symbol dne x : π(¬ ¬ x) → π x
    // todo: add proof encoding
    override def name: lpConstantTerm = lpConstantTerm("dne")

    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"), lpOtype.lift2Meta)),lpMlFunctionType(Seq(lpOlUnaryConnectiveTerm(lpNot,lpOlUnaryConnectiveTerm(lpNot,lpOlConstantTerm("x"))).prf,lpOlConstantTerm("x").prf)))

    override def pretty: String = lpDeclaration(lpDne.name, Seq.empty, lpDne.ty).pretty
  }

  case object lpPropExt extends lpAxioms {
    override def name: lpConstantTerm = lpConstantTerm("propExt")

    // Π x: Els (↑ o), Π y: Els (↑ o), (Prf x → Prf y) → (Prf y → Prf x) → Prf (eq x y)
    override def ty: lpMlType = lpMlDependType(Seq(lpTypedVar(lpConstantTerm("x"), lpOtype.lift2Meta),lpTypedVar(lpConstantTerm("y"), lpOtype.lift2Meta)), lpMlFunctionType(Seq(lpMlFunctionType(Seq(lpOlConstantTerm("x").prf,lpOlConstantTerm("y").prf)),lpMlFunctionType(Seq(lpOlConstantTerm("y").prf,lpOlConstantTerm("x").prf)),lpOlTypedBinaryConnectiveTerm(lpEq,lpOtype,lpOlConstantTerm("x"),lpOlConstantTerm("y")).prf)))

    override def pretty: String = lpDeclaration(lpPropExt.name, Seq.empty, lpPropExt.ty).pretty
  }


  // todo: properly encode this using the datastructures
  val ExTTenc = "require open Stdlib.Set Stdlib.Prop Stdlib.FOL Stdlib.Eq Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.HOL Stdlib.Impred;\n\nsymbol propExt x y : (π x → π y) → (π y → π x) → π (x = y);\nsymbol funExt [T S] (f g : (τ (T ⤳ S))) : π(∀(λ x, (f x) = (g x))) → π(f = g);\n\nsymbol em x : π((x ∨ ¬ x));\n\nopaque symbol dne x : π(¬ ¬ x) → π x ≔\nbegin\n    assume x h1;\n    refine ∨ₑ (em x) _ _\n        {assume h2;\n        refine h2}\n        {assume h2;\n        refine ⊥ₑ (h1 h2)}\nend;"
  // todo: this version of output permLib includes many definitions that will not be necessary since they will be made part of the stdlib!
  val permLib = "/* Library on Meta-Theorems for Disjunctions\n\n-------------------\n\nThe library aims to prove the following meta-theorems for disjunctions:\n\n** Permutation Theorem:\n   The theorem is instantiated with:\n   - A list of natural numbers representing a disjunction.\n   - A list of terms of type `o` representing a clause.\n\n   The theorem verifies that the permuted clause still contains all literals of the original clause. \n   If so, it maps the disjunction of the original clause to the disjunction after the permutation.\n\n** Double Literal Deletion Theorem:\n   The theorem is instantiated with three lists:\n   - A list of natural numbers representing the indices of literals in the original list. \n     For literals occurring multiple times, the index of the first occurrence is used for all of the\n     subsequent occurrences. For example, for `π (l0 ∨ l1 ∨ l2 ∨ l1)`, this list would be `(0, 1, 2, 1)`.\n   - A second list of natural numbers indicating the desired positions of the literals in the clause.\n     If for instance the second occurrence of `l1` in `π (l0 ∨ l1 ∨ l2 ∨ l1)` should be deleted, the \n     derived clause would be `π (l0 ∨ l1 ∨ l2)`, and the list that must be provided would be (0, 1, 2).\n     To delete the first occurrence of `l1`, and derive the clause `π (l0 ∨ l2 ∨ l1)`, the list would \n     be (0, 2, 1).\n   3. A list of terms of type `o`, representing literals.\n\n   The resulting theorem verifies if each literal from the original clause is still present at least once \n   in the derived clause. If so, it maps the disjunction of the original literals to the disjunction after \n   the desired double literal deletion. This approach allows multiple identical literals to be deleted at once.\n\n** Transformation Theorem:\n   This theorem is useful when a rule is applied to only one literal of a clause. \n   For example, consider the clause `π (l0 ∨ l1 ∨ l2 ∨ l3)` and an inference rule `π l2 → π l2'`. \n   The transformation theorem can be instantiated with:\n   - The list of terms of type `o` representing the original clause.\n   - The position of the literal being affected.\n   - The inference rule.\n\n   The resulting term maps the original disjunction to one with the transformed literal.\n\n---\n\n** General Concept:\n   The general idea behind the permutation and double literal deletion theorems is to evaluate a list of natural \n   numbers representing the positions of literals after respective operations with respect to the list of literals. \n   A computation ensures the operation is admissible:\n   - In the case of permutations, all literals must still be present in the permuted clause.\n   - In the case of double literal deletion, each literal must still be present at least once.\n   If these conditions are fulfilled, the corresponding argument in the theorem will compute to `π ⊤` and can simply\n   be instantiated with `⊤ᵢ` (examples are given below).\n\n---\n\n** Defined Operations:\n                        `indexes l`: Returns a list of the indices of the list `l`.\n                      `literal n l`: Returns the element of the list `l` at index `n`.\n                `literals ln l`: Takes as arguments a list `ln` of natural numbers and a list `l` and \n                                  returns a list of  the elements of `l` ordered according to the indices in `ln`.\n                        `disj l`: Returns the disjunction of all literals in the list `l`.\n       `bincludes [a] eqb l1 l2`: For two lists `l1` and `l2` of type `a` and a boolean equality relation `eqb` \n                                  for elements of type `a`, this operation returns `true` if `l2` includes all \n                                  elements of `l1`, and `false` otherwise.\n      `preserves_contents ln lo`: Takes a list of natural numbers (`ln`) and a list of terms of type `o` (`lo`) \n                                  as arguments. Returns `true` if every index of `lo` is included in `ln`.\n*/\n\nrequire open Stdlib.Set Stdlib.Prop Stdlib.FOL Stdlib.Eq Stdlib.Nat Stdlib.Bool Stdlib.List Stdlib.Impred;\n\n\n// parch for the old STD-lib version\nnotation ∨ infix right 6;\ncoerce_rule coerce \uD835\uDD39 Prop $x ↪ istrue $x;\nsymbol eqn_complete x y : π(x = y) → π(istrue(eqn x y));\n\n\nsymbol iota : ℕ → ℕ → \uD835\uDD43 nat;\nrule iota $n 0 ↪ □\nwith iota $n ($k +1) ↪ $n ⸬ iota ($n +1) $k;\nsymbol indexes [a] : \uD835\uDD43 a → \uD835\uDD43 nat;\nrule indexes $l ↪ iota 0 (size $l);\n\nassert l0 l1 l2 ⊢ indexes (l0 ⸬ l1 ⸬ l2  ⸬ l1 ⸬ □) ≡ 0 ⸬ (1 ⸬ (2 ⸬ (3 ⸬ □)));\n\nopaque symbol mem_rcons_left [a] beq (n m : τ a) (l : \uD835\uDD43 a) :\n  π (∈ beq n l) → π (∈ beq n (rcons l m)) ≔\nbegin\n  assume a beq n m;\n  induction\n    { assume h; refine ⊥ₑ h }\n    { assume n0 l h1 h2;\n      have H0: π (beq n n0) → π (beq n n0 or ∈ beq n (rcons l m))\n        { assume h3;\n          refine (orᵢ₁ [beq n n0] (∈ beq n (rcons l m)) h3) };\n          have H1: π (∈ beq n l) →  π (beq n n0 or ∈ beq n (rcons l m))\n            { assume h3;\n              refine (orᵢ₂ (beq n n0) [∈ beq n (rcons l m)] (h1 h3)) };\n          refine orₑ [beq n n0] [∈ beq n l] (beq n n0 or ∈ beq n (rcons l m)) h2 H0 H1 }\nend;\n\nopaque symbol 0∈indexes⸬ [a] (x : τ a) (l: \uD835\uDD43 a) :\n  π (∈ eqn 0 (indexes (x ⸬ l))) ≔\nbegin\n    assume a x;\n    induction\n        {refine ⊤ᵢ}\n        {assume y l h;\n        refine mem_rcons_left eqn 0 (size l +1) (indexes (x ⸬ l)) h }\nend;\n\nsymbol +1∈iota+1 n m k :\n  π (∈ eqn n (iota m k)) → π (∈ eqn (n +1) (iota (m +1) k)) ≔\nbegin\n  assume n;\n  have h: Π k m, π (∈ eqn n (iota m k)) → π (∈ eqn (n +1) (iota (m +1) k))\n    { induction\n      { assume m; simplify; assume h; refine h }\n      { assume k h1 m; simplify; assume h2;\n        refine orₑ [eqn n m] [∈ eqn n (iota (m +1) k)] (eqn n m or ∈ eqn (n +1) (iota ((m +1) +1) k)) h2 _ _\n          { assume h3;\n            refine orᵢ₁ [eqn n m] (∈ eqn (n +1) (iota ((m +1) +1) k)) h3 }\n          { assume h3;\n            refine orᵢ₂ (eqn n m) [∈ eqn (n +1) (iota ((m +1) +1) k)] _;\n            refine h1 (m +1) _; refine h3\n          }\n      }\n    };\n  assume m k; refine h k m\nend;\n\nopaque symbol +1∈indexes⸬ a (n: τ nat) (l: \uD835\uDD43 a) (y: τ a) :\n  π (∈ eqn n (indexes l)) → π (∈ eqn (n +1) (indexes (y ⸬ l))) ≔\nbegin\n  assume a n; induction\n  { simplify; assume x h; refine h }\n  { assume x l h y; simplify; assume i;\n  type orₑ [eqn n 0] [∈ eqn n (iota 1 (size l))] _ i _ _;\n    refine orₑ [eqn n 0] [∈ eqn n (iota 1 (size l))] (eqn n 0 or ∈ eqn (n +1) (iota 2 (size l))) i _ _\n      { assume j; apply orᵢ₁ [eqn n 0] (∈ eqn (n +1) (iota 2 (size l))) j }\n      { assume j; apply orᵢ₂ (eqn n 0) [∈ eqn (n +1) (iota 2 (size l))] _;\n        refine +1∈iota+1 n 1 (size l) j;\n      }\n  }\nend;\n\n\n// literal \n\nsymbol literal : τ nat → \uD835\uDD43 o → τ o;\nrule literal $n $list ↪ nth ⊥ $list $n;\n\nassert l0 l1 l2 ⊢ literal 1 (l0 ⸬ l1 ⸬ l2 ⸬ l1 ⸬ □) ≡ l1;\n\nopaque symbol lit_ext (l: \uD835\uDD43 o) (l0 : τ o) (n: τ nat) : \n    π (literal n l) → π (literal (n +1) (l0 ⸬ l)) ≔\nbegin\n    assume l l0 n;\n    simplify;\n    assume h1;\n    refine h1\nend;\n\n\n// literals\n\nsymbol literals: \uD835\uDD43 nat → \uD835\uDD43 o → \uD835\uDD43 o;\nrule literals ($n ⸬ $l) $list ↪ (nth ⊥ $list $n) ⸬ (literals $l $list)\nwith literals □ _ ↪ □;\n\nassert l0 l1 l2 ⊢ literals (1 ⸬ 2 ⸬ 0 ⸬ 3 ⸬ □) (l0 ⸬ l1 ⸬ l2  ⸬ l1 ⸬ □) ≡ l1 ⸬ (l2  ⸬ (l0 ⸬ (l1 ⸬ □)));\n\n\n// disj\n\nsymbol disj : \uD835\uDD43 o → τ o;\nrule disj ($l1 ⸬ ($c ⸬ $l)) ↪ ($l1 ∨ disj ($c ⸬ $l))\nwith disj ($l1 ⸬ □) ↪ $l1 \nwith disj □ ↪ ⊥;\n\nassert l0 l1 l2 ⊢ π (disj (l0 ⸬ l1 ⸬ l2  ⸬ l1 ⸬ □)) ≡ π (l0 ∨ (l1 ∨ (l2  ∨ l1)));\n\nopaque symbol disj_head (l0 : τ o) (l : \uD835\uDD43 o) : \n    π (l0) → π (disj (l0 ⸬ l)) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine h1}   \n        {assume x0 l1 h1; \n        assume h2; \n        refine ∨ᵢ₁ h2}\nend; \n\nopaque symbol disj_tail (l0 : τ o) (l : \uD835\uDD43 o) : \n    π (disj l) → π (disj (l0 ⸬ l)) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine ⊥ₑ h1}\n        {assume x1 l1 h1 h2;\n        refine ∨ᵢ₂ h2}\nend;\n\nopaque symbol disj_correct (l0 : τ o) (l : \uD835\uDD43 o) : \n    π (disj (l0 ⸬ l)) → π (l0 ∨ disj l) ≔\nbegin\n    assume l0;\n    induction\n        {assume h1;\n        refine ∨ᵢ₁ h1}\n        {assume x1 l1 h1 h2;\n        refine h2}\nend;\n\nopaque symbol lit_imp_disj (lit_list: \uD835\uDD43 o) (pos_list: \uD835\uDD43 nat) : \n    π (∃(λ x, (literal x lit_list) ∧ (∈ eqn x pos_list))) → π (disj (literals pos_list lit_list)) ≔\nbegin\n    assume lit_list;\n    induction\n        {simplify;\n        assume h1;\n        have H0: (Π x: τ nat, π ((λ x1, nth ⊥ lit_list x1 ∧ ⊥) x) → π ⊥)\n            {assume x h2;\n            refine ∧ₑ₂ h2};\n        refine ∃ₑ h1 H0}\n        {assume n l;\n        simplify;\n        assume h1 h2;\n        have H1 : Π x: τ nat, π ((λ x1, nth ⊥ lit_list x1 ∧ (eqn x1 n or ∈ eqn x1 l)) x) → π (disj (nth ⊥ lit_list n ⸬ literals l lit_list))\n            {assume m h3;\n            have H0 : π ((eqn m n) ∨ (∈ eqn m l))\n                {refine ∨_istrue [eqn m n] [∈ eqn m l] (∧ₑ₂ h3)};\n            have H1 : π (eqn m n) → π (disj (nth ⊥ lit_list n ⸬ literals l lit_list))\n                {assume h4;\n                have H1_0 : π (nth ⊥ lit_list n)\n                    {have H1_0_0 : π (n = m)\n                        {symmetry;\n                        refine eqn_correct m n h4};\n                    rewrite H1_0_0;\n                    refine ∧ₑ₁ h3};\n                refine disj_head (nth ⊥ lit_list n) (literals l lit_list) H1_0};\n            have H2 : π (∈ eqn m l) → π (disj (nth ⊥ lit_list n ⸬ literals l lit_list))\n                {assume h4;\n                have H2_0 : π `∃ x, nth ⊥ lit_list x ∧ (∈ eqn x l)\n                    {have H2_0_0 : π ((λ x, nth ⊥ lit_list x ∧ (∈ eqn x l)) m)\n                        {refine ∧ᵢ (∧ₑ₁ h3) h4};\n                    refine ∃ᵢ m H2_0_0};\n                refine disj_tail (nth ⊥ lit_list n) (literals l lit_list) (h1 H2_0)};\n            refine ∨ₑ H0 H1 H2\n            };\n        refine ∃ₑ h2 H1}   \nend;\n\nopaque symbol disj_imp_lit (l: \uD835\uDD43 o) : \n    π (disj l) → π (∃(λ (x : τ nat), (literal x l) ∧ (∈ eqn x (indexes l)))) ≔\nbegin\n    induction\n        {assume h1;\n        refine ⊥ₑ h1}\n        {assume l0 l h1 h2;\n        have H0: π (l0 ∨ disj l)\n            {refine disj_correct l0 l h2};\n        have H1: π l0 → π (`∃ x, (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l))))\n            {assume h3;\n            have H1_0 : π (literal 0 (l0 ⸬ l))\n                {simplify;\n                refine h3};\n            have H1_1 : π ((λ x, literal x (l0 ⸬ l) ∧ (∈ eqn x (indexes (l0 ⸬ l)))) 0)\n                {simplify;\n                refine ∧ᵢ H1_0 (0∈indexes⸬ l0 l)};\n            refine ∃ᵢ [nat] [(λ x, literal x (l0 ⸬ l) ∧ (∈ eqn x (indexes (l0 ⸬ l))))] 0 H1_1};\n        have H2: π (disj l) → π (`∃ x, (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l))))\n            {assume h3;\n            have H2_0 : Π x0 , π ((λ x, literal x l ∧ (∈ eqn x (indexes l))) x0) → π (`∃ x, (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l))))\n                {assume n h4;\n                have H2_0_0 : π ((λ x , (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l)))) (n +1))\n                    {refine ∧ᵢ (lit_ext l l0 n ((∧ₑ₁ h4))) (+1∈indexes⸬ o n l l0 ((∧ₑ₂ h4)))};\n                refine ∃ᵢ [nat] [λ x , (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l)))] (n +1) H2_0_0\n                };\n            refine ∃ₑ (h1 h3) [`∃ x, (literal x (l0 ⸬ l)) ∧ (∈ eqn x (indexes (l0 ⸬ l)))] H2_0};\n        refine ∨ₑ H0 H1 H2};\nend;\n\nopaque symbol x_in_x⸬ [a] (l: \uD835\uDD43 a) (l0 : τ a) (beq: τ a → τ a → \uD835\uDD39) : \n    (Π x, π (beq x x)) → π (∈ beq l0 (l0 ⸬ l)) ≔\nbegin\n    assume a l l0 beq h1;\n    refine orᵢ₁ [beq l0 l0] (∈ beq l0 l) (h1 l0)\nend;\n\nopaque symbol in⸬ [a] (beq: τ a → τ a → \uD835\uDD39) (n m: τ a) (l: \uD835\uDD43 a) : \n    π (∈ beq n l) → π (∈ beq n (m ⸬ l)) ≔\nbegin\n    assume a beq n m;\n    induction\n        {assume h1;\n        refine ⊥ₑ h1}\n        {assume n0 l;\n        assume h1 h2;\n        have H0: π (beq n n0) →  π (beq n m or (beq n n0 or ∈ beq n l))\n            {assume h3;\n            refine orᵢ₂ (beq n m) [beq n n0 or ∈ beq n l] (orᵢ₁ [beq n n0] (∈ beq n l) h3)};\n        have H1: π (∈ beq n l) →  π (beq n m or (beq n n0 or ∈ beq n l))\n            {assume h3;\n            refine orᵢ₂ (beq n m) [beq n n0 or ∈ beq n l] (orᵢ₂ (beq n n0) [∈ beq n l] h3)};\n        refine orₑ [beq n n0] [∈ beq n l] (beq n m or (beq n n0 or ∈ beq n l)) h2 H0 H1}\nend;\n\nopaque symbol disj_imp_lit_pos (lit_list: \uD835\uDD43 o) (pos_list: \uD835\uDD43 nat): \n    π (disj (literals pos_list lit_list)) → π (∃(λ (x : τ nat), (literal x lit_list) ∧ (∈ eqn x pos_list))) ≔\nbegin\n    assume lit_list;\n    induction\n        {assume h1;\n        refine ⊥ₑ h1}\n        {assume l0 pos_list;\n        assume h1 h2;\n        have H0: π ((nth ⊥ lit_list l0) ∨ disj (literals pos_list lit_list))\n            {refine disj_correct (nth ⊥ lit_list l0) (literals pos_list lit_list) h2};\n        have H1: π (nth ⊥ lit_list l0) → π (`∃ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list)))\n            {assume h3;\n            have H1_0 : π (literal l0 lit_list)\n                {refine h3};\n            have H1_1 : π ((λ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list))) l0)\n                {refine ∧ᵢ H1_0 (x_in_x⸬ pos_list l0 eqn (λ x, (eqn_complete x x (eq_refl x))))};\n        refine ∃ᵢ [nat] [λ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list))] l0 H1_1};\n        have H2: π (disj (literals pos_list lit_list)) → π (`∃ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list)))\n            {assume h3;\n            have H2_0: (Π x: τ nat, π ((λ x1, literal x1 lit_list ∧ (∈ eqn x1 pos_list)) x) → π (`∃ x1, literal x1 lit_list ∧ (∈ eqn x1 (l0 ⸬ pos_list))))\n                {assume n h4;\n                have H2_0_0 : π ((λ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list))) n)\n                    {refine ∧ᵢ (∧ₑ₁ h4) (in⸬ eqn n l0 pos_list (∧ₑ₂ h4))};\n                refine ∃ᵢ [nat]  [λ x , literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list))] n H2_0_0};\n            refine ∃ₑ (h1 h3) [`∃ x, literal x lit_list ∧ (∈ eqn x (l0 ⸬ pos_list))] H2_0};    \n        refine ∨ₑ H0 H1 H2}\nend;\n\n\n// bincludes\n\nsymbol bincludes  [a] : (τ a → τ a → \uD835\uDD39) → \uD835\uDD43 a → \uD835\uDD43 a → \uD835\uDD39;\nrule bincludes $beq ($k0 ⸬ $k) $l ↪ (∈ $beq $k0 $l) and (bincludes $beq $k $l)\nwith bincludes _ □ _ ↪ true;\n\nassert ⊢ bincludes eqn (0 ⸬ 1 ⸬ □) (1 ⸬ 2 ⸬ 0 ⸬ 3 ⸬ □) ≡ true;\n\nopaque symbol bincludes_el (n: τ nat) (σ: \uD835\uDD43 nat) (ln: \uD835\uDD43 nat): \n    π (bincludes eqn ln σ) → π (∈ eqn n ln) → π (∈ eqn n σ) ≔\nbegin\n    assume n σ;\n    induction\n        {assume h1 h2;\n        refine ⊥ₑ h2}\n        {assume m ln h1 h2 h3;\n        have H1: π (eqn n m) → π (∈ eqn n σ) \n            {assume h4;\n            have H1_0 : π (n = m)\n                {refine eqn_correct n m h4};\n            rewrite H1_0;\n            refine andₑ₁ [∈ eqn m σ] [bincludes eqn ln σ] h2};\n        have H2: π (∈ eqn n ln) → π (∈ eqn n σ)\n            {assume h4;\n            refine h1 (andₑ₂ [∈ eqn m σ] [bincludes eqn ln σ] h2) h4};\n        refine orₑ [eqn n m] [∈ eqn n ln] (∈ eqn n σ) h3 H1 H2}\nend;\n\n\n// preserves_contents\n\nsymbol preserves_contents: \uD835\uDD43 nat → \uD835\uDD43 o → \uD835\uDD39;\nrule preserves_contents  $f $l ↪ bincludes eqn (indexes $l) $f;\n\nassert l0 l1 l2 ⊢ preserves_contents (1 ⸬ 2 ⸬ 0 ⸬ 3 ⸬ □) (l0 ⸬ l1 ⸬ l2 ⸬ l1 ⸬ □) ≡ true;\n\nopaque symbol preserves_contents_el (n: τ nat) (σ : \uD835\uDD43 nat) (l: \uD835\uDD43 o) : \n    π (preserves_contents σ l) →  π (∈ eqn n (indexes l)) → π (∈ eqn n σ) ≔\nbegin\n    assume n σ l;\n    simplify;\n    assume h1 h2;\n    refine bincludes_el n σ (indexes l) h1 h2;   \nend;\n\n\n////////////////////////////////////////////////////////////////////////////////\n///////////////////////////////// meta-therems /////////////////////////////////\n////////////////////////////////////////////////////////////////////////////////\n\n// permutation theorem \n\nopaque symbol perm_theorem (σ : \uD835\uDD43 nat) (c: \uD835\uDD43 o) : \n    π (preserves_contents σ c) → π(disj c) → π(disj (literals σ c)) ≔\nbegin\n    assume σ c h1 h2;\n\n    have H1: (Π x: τ nat, π ((λ x1, (literal x1 c) ∧ (∈ eqn x1 (indexes c))) x) → π (∃(λ y ,(literal y c) ∧ (∈ eqn y σ))))\n        {assume x0 h3;\n        refine (∃ᵢ [nat] [λ y ,(literal y c) ∧ (∈ eqn y σ)] x0) (∧ᵢ (∧ₑ₁ h3) (preserves_contents_el x0 σ c h1 (∧ₑ₂ h3)))};\n    \n    have H2: π (∃(λ y ,(literal y c) ∧ (∈ eqn y σ)))\n        {refine ∃ₑ (disj_imp_lit c h2) H1};\n\n    refine  lit_imp_disj c σ H2;\nend;\n\nassert l0 l1 l2 ⊢ perm_theorem (1 ⸬ 2 ⸬ 0 ⸬ 3 ⸬ □) (l0 ⸬ l1 ⸬ l2 ⸬ l0 ⸬ □) ⊤ᵢ : π (l0 ∨ l1 ∨ l2 ∨ l0) → π (l1 ∨ l2 ∨ l0 ∨ l0);\n\n\n// double literal deletion theorem\n\nopaque symbol double_lit_del_theorem (id_list : \uD835\uDD43 nat) (output_list : \uD835\uDD43 nat) (c: \uD835\uDD43 o) : \n    π (bincludes eqn id_list output_list) → π(disj (literals id_list c)) → π(disj (literals output_list c)) ≔\nbegin\n    assume id_list output_list c h1 h2;\n    refine lit_imp_disj c output_list _;\n    refine ∃ₑ (disj_imp_lit_pos c id_list h2) _;\n    assume n h3;\n    refine (∃ᵢ [nat] [λ x, literal x c ∧ (∈ eqn x output_list)] n) (∧ᵢ (∧ₑ₁ h3) (bincludes_el n output_list id_list h1 (∧ₑ₂ h3)))\nend;\n\nassert l0 l1 l2 ⊢ double_lit_del_theorem (0 ⸬ 1 ⸬ 2 ⸬ 1 ⸬ □) (0 ⸬ 1 ⸬ 2 ⸬ □) (l0 ⸬ l1 ⸬ l2 ⸬ l1 ⸬ □) ⊤ᵢ : π (l0 ∨ l1 ∨ l2 ∨ l1) → π (l0 ∨ l1 ∨ l2);\n\n\n// transformation theorem \n\nopaque symbol transformation_theorem [l : τ o] (c: \uD835\uDD43 o) (n : τ nat) : \n    π ((nth ⊥ c n) ⇒ l) → π (disj c) → π (disj (set_nth ⊥ c n l)) ≔\nbegin\n    assume l;\n    induction\n        {simplify;\n        assume x h1 h2;\n        refine ⊥ₑ h2}\n        {assume x clause h1;\n        induction\n            {simplify;\n            assume h2 h3;\n            have H0: π (x ∨ (disj clause))\n                {refine disj_correct x clause h3};\n            have H1: π x → π (disj (l ⸬ clause))\n                {assume h4;\n                refine disj_head l clause (h2 h4)};\n            have H2: π (disj clause) → π (disj (l ⸬ clause))\n                {assume h4;\n                refine disj_tail l clause h4};   \n            refine ∨ₑ H0 H1 H2}\n            {assume n h2 h3 h4;\n            have H00: π (x ∨ (disj clause)) \n                {refine disj_correct x clause h4};\n            have H10: π x → π (disj (x ⸬ set_nth ⊥ clause n l))\n                {assume h5;\n                refine disj_head x (set_nth ⊥ clause n l) h5};\n            have H20:  π (disj clause) → π (disj (x ⸬ set_nth ⊥ clause n l))\n                {assume h5;\n                have H2_0 : π (disj (set_nth ⊥ clause n l))\n                    {refine h1 n h3 h5};\n                refine disj_tail x (set_nth ⊥ clause n l) H2_0};\n            refine ∨ₑ H00 H10 H20}}\nend;\n\nassert l0 l1 l2 l2' ⊢ transformation_theorem [l2'] (l0 ⸬ l1 ⸬ l2 ⸬ l1 ⸬ □) 2 : (π l2 → π l2') →  π (l0 ∨ l1 ∨ l2 ∨ l1) → π (l0 ∨ l1 ∨ l2' ∨ l1);"

  val simpLib = "\n/******************************************************************************\n *  Simplifications          \n ******************************************************************************/\n\n// Idempotence and Contradiction for ∧ and ∨\n\nopaque symbol ∨_idem x :\n  π ((x ∨ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (x ∨ x) x _ _\n    {assume h1;\n     refine ∨ₑ h1 _ _\n       {assume h2; refine h2}\n       {assume h2; refine h2}}\n    {assume h2; refine ∨ᵢ₁ h2}\nend;\n\nopaque symbol ∧_idem x :\n  π ((x ∧ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (x ∧ x) x _ _\n    {assume h1; refine ∧ₑ₁ h1}\n    {assume h1; refine ∧ᵢ h1 h1}\nend;\n\nopaque symbol ∧_contra_l x :\n  π ((¬ x ∧ x) = ⊥) ≔\nbegin\n  assume x;\n  refine propExt (¬ x ∧ x) ⊥ _ _\n    {assume h1;\n     refine (∧ₑ₁ h1) (∧ₑ₂ h1)}\n     {assume h1; refine ⊥ₑ h1}\nend;\n\nopaque symbol ∧_contra_r x :\n  π ((x ∧ ¬ x ) = ⊥) ≔\nbegin\n  assume x;\n  refine propExt (x ∧ ¬ x) ⊥ _ _\n    {assume h1; refine (∧ₑ₂ h1) (∧ₑ₁ h1)}\n    {assume h1; refine ⊥ₑ h1}\nend;\n\n\n// Disjunction/Conjunction with ⊤ / ⊥      \n\nopaque symbol ∨⊤ x :\n  π ((x ∨ ⊤) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (x ∨ ⊤) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h2; refine ∨ᵢ₂ h2}\nend;\n\nopaque symbol ⊤∨ x :\n  π ((⊤ ∨ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (⊤ ∨ x) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h2; refine ∨ᵢ₁ h2}\nend;\n\nopaque symbol ∧⊤ x :\n  π ((x ∧ ⊤) = x) ≔\nbegin\n  assume x;\n  refine propExt (x ∧ ⊤) x _ _\n    {assume h1; refine ∧ₑ₁ h1}\n    {assume h1; refine ∧ᵢ h1 ⊤ᵢ}\nend;\n\nopaque symbol ⊤∧ x :\n  π ((⊤ ∧ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (⊤ ∧ x) x _ _\n    {assume h1; refine ∧ₑ₂ h1}\n    {assume h1; refine ∧ᵢ ⊤ᵢ h1}\nend;\n\nopaque symbol ∨⊥ x :\n  π ((x ∨ ⊥) = x) ≔\nbegin\n  assume x;\n  refine propExt (x ∨ ⊥) x _ _\n    {assume h1;\n     refine ∨ₑ h1 _ _\n       {assume h2; refine h2}\n       {assume h2; refine ⊥ₑ h2}}\n    {assume h1; refine ∨ᵢ₁ h1}\nend;\n\nopaque symbol ⊥∨ x :\n  π ((⊥ ∨ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (⊥ ∨ x) x _ _\n    {assume h1;\n    refine ∨ₑ h1 _ _\n        {assume h2; refine ⊥ₑ h2}\n        {assume h2; refine h2}}\n    {assume h1; refine ∨ᵢ₂ h1}\nend;\n\nopaque symbol ∧⊥ x :\n  π ((x ∧ ⊥) = ⊥) ≔\nbegin\n  assume x;\n  refine propExt (x ∧ ⊥) ⊥ _ _\n    {assume h1; refine ∧ₑ₂ h1}\n    {assume h1;\n     type ⊥ₑ h1;\n     refine ∧ᵢ (⊥ₑ h1) h1}\nend;\n\nopaque symbol ⊥∧ x :\n  π ((⊥ ∧ x) = ⊥) ≔\nbegin\n  assume x;\n  refine propExt (⊥ ∧ x) ⊥ _ _\n    {assume h1; refine ∧ₑ₁ h1}\n    {assume h1; refine ⊥ₑ h1}\nend;\n\n\n// Negation of ⊤ and ⊥  \n\nopaque symbol ¬⊥ :\n  π (¬ ⊥ = ⊤) ≔\nbegin\n  refine propExt (¬ ⊥) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h1 h2; refine h2}\nend;\n\nopaque symbol ¬⊤ :\n  π (¬ ⊤ = ⊥) ≔\nbegin\n  refine propExt (¬ ⊤) ⊥ _ _\n    {assume h1; refine h1 ⊤ᵢ}\n    {assume h1; refine ⊥ₑ h1}\nend;\n\n\n//Equalities on Elements   \n\nopaque symbol eq_idem (T : Set) (x : τ T) : \n  π ((x = x) = ⊤) ≔\nbegin\n  assume T x;\n  refine propExt (x = x) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h1; refine eq_refl x}\nend;\n\nopaque symbol ¬eq_idem (T : Set) (x : τ T) :\n  π (¬ (x = x) = ⊥) ≔\nbegin\n  assume T x;\n  refine propExt (¬ (x = x)) ⊥ _ _\n    {assume h1;\n     have xx_ineq: π(x = x) → π ⊥\n       {assume h2; refine h1 h2};\n     refine xx_ineq (eq_refl [T] x)}\n    {assume h1; refine ⊥ₑ h1}\nend;\n\nopaque symbol eq⊤ x :\n  π ((x = ⊤) = x) ≔\nbegin\n  assume x;\n  refine propExt (x = ⊤) x _ _\n    {assume h1;\n     refine (ind_eq h1 (λ z, z)) ⊤ᵢ}\n    {assume h1;\n     refine propExt x ⊤ _ _\n        {assume h2; refine ⊤ᵢ}\n        {assume h2; refine h1}}\nend;\n\nopaque symbol ⊤eq x :\n  π ((⊤ = x) = x) ≔\nbegin\n  assume x;\n  refine propExt (⊤ = x) x _ _\n    {assume h1;\n    refine (ind_eq (eq_sym h1) (λ z, z)) ⊤ᵢ}\n    {assume h1;\n    refine propExt ⊤ x _ _\n        {assume h2; refine h1}\n        {assume h2; refine ⊤ᵢ}}\nend;\n\nopaque symbol ¬eq⊤ x :\n  π (¬(x = ⊤) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (¬(x = ⊤)) (¬ x) _ _\n    {assume h1 h2;\n     refine h1 (propExt x ⊤ _ _)\n        {assume h3; refine ⊤ᵢ}\n        {assume h3; refine h2}}\n    {assume h1 h2;\n     have x_true: π x\n       {refine ind_eq h2 (λ z, z) ⊤ᵢ};\n     refine h1 x_true}\nend;\n\nopaque symbol ¬⊤eq x :\n  π (¬(⊤ = x) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (¬(⊤ = x)) (¬ x) _ _\n    {assume h1 h2;\n     refine h1 (propExt ⊤ x _ _)\n        {assume h3; refine h2}\n        {assume h3; refine ⊤ᵢ}}\n    {assume h1 h2;\n     have x_true: π x\n        {refine ind_eq (eq_sym h2) (λ z, z) ⊤ᵢ};\n     refine h1 x_true}\nend;\n\nopaque symbol eq⊥ x :\n  π ((x = ⊥) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (x = ⊥) (¬ x) _ _\n  {assume h1 h2;\n   refine (ind_eq (eq_sym h1) (λ z, z)) h2}\n  {assume h2;\n   refine propExt x ⊥ _ _\n   {assume h3; refine h2 h3}\n   {assume h3; refine ⊥ₑ h3}}\nend;\n\nopaque symbol ⊥eq x :\n  π ((⊥ = x) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (⊥ = x) (¬ x) _ _\n  {assume h1 h2;\n   refine (ind_eq h1 (λ z, z)) h2}\n  {assume h2;\n   refine propExt ⊥ x _ _\n   {assume h3; refine ⊥ₑ h3}\n   {assume h3; refine h2 h3}}\nend;\n\nopaque symbol  ¬eq⊥ x :\n  π (¬ (x = ⊥) = x) ≔\nbegin\n  assume x;\n  refine propExt (¬(x = ⊥)) x _ _\n  {assume h1;\n   refine ∨ₑ (em x) _ _\n   {assume h2; refine h2}\n   {assume h2;\n    have eq_x_⊥: π (x = ⊥)\n    {refine propExt x ⊥ _ _\n     {assume h3; refine h2 h3}\n     {assume h3; refine ⊥ₑ h3}};\n    have contra: π ⊥\n    {refine h1 eq_x_⊥};\n    refine ⊥ₑ contra}}\n  {assume h2 eq_x_⊥;\n   refine (ind_eq (eq_sym eq_x_⊥) (λ z, z)) h2}\nend;\n\nopaque symbol ¬⊥eq x :\n  π (¬ (⊥ = x) = x) ≔\nbegin\n  assume x;\n  refine propExt (¬(⊥ = x)) x _ _\n  {assume h1;\n   refine ∨ₑ (em x) _ _\n   {assume h2; refine h2}\n   {assume h2;\n    have eq_⊥_x: π (⊥ = x)\n    {refine propExt ⊥ x _ _\n     {assume h3; refine ⊥ₑ h3}\n     {assume h3; refine h2 h3}};\n    have contra: π ⊥\n    {refine h1 eq_⊥_x};\n    refine ⊥ₑ contra}}\n  {assume h2 eq_⊥_x;\n   refine (ind_eq eq_⊥_x (λ z, z)) h2}\nend;\n\n\n// Simplifications on Implication\n\nopaque symbol ⇒_idem x :\n  π ((x ⇒ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (x ⇒ x) ⊤ _ _\n  {assume h1; refine ⊤ᵢ}\n  {assume h2 y; refine y}\nend;\n\nopaque symbol ⊤⇒ x :\n  π ((⊤ ⇒ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (⊤ ⇒ x) x _ _\n  {assume h1; refine h1 ⊤ᵢ}\n  {assume h2 y; refine h2}\nend;\n\nopaque symbol ⇒⊤ x :\n  π ((x ⇒ ⊤) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (x ⇒ ⊤) ⊤ _ _\n  {assume h1; refine ⊤ᵢ}\n  {assume h2 y; refine ⊤ᵢ}\nend;\n\nopaque symbol ⊥⇒ x :\n  π ((⊥ ⇒ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (⊥ ⇒ x) ⊤ _ _\n  {assume h1; refine ⊤ᵢ}\n  {assume h2 h3; refine ⊥ₑ h3}\nend;\n\nopaque symbol ⇒⊥ x :\n  π ((x ⇒ ⊥) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (x ⇒ ⊥) (¬ x) _ _\n  {assume h1 h2; refine h1 h2}\n  {assume h2 y; refine h2 y}\nend;\n\n\n// Simplifications on Bi-Implication\n\nopaque symbol ⇔⊤ x :\n  π ((x ⇔ ⊤) = x) ≔\nbegin\n  assume x;\n  refine propExt (x ⇔ ⊤) x _ _\n  {assume h1;\n   refine ∧ₑ₂ h1 ⊤ᵢ}\n  {assume h2;\n   refine ∧ᵢ _ _\n   {assume h3; refine ⊤ᵢ} \n   {assume h3; refine h2}}\nend;\n\nopaque symbol ⊤⇔ x :\n  π ((⊤ ⇔ x) = x) ≔\nbegin\n  assume x;\n  refine propExt (⊤ ⇔ x) x _ _\n  {simplify;assume h1;\n   refine ∧ₑ₁ h1 ⊤ᵢ}\n  {assume h2;\n   refine ∧ᵢ _ _\n   {assume h3; refine h2}\n   {assume h3; refine ⊤ᵢ}}\nend;\n\nopaque symbol ⊥⇔ x :\n  π ((⊥ ⇔ x) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (⊥ ⇔ x) (¬ x) _ _\n  {assume h1;\n   refine ∧ₑ₂ h1}\n  {assume h2;\n   refine ∧ᵢ _ _\n   {assume h3; refine ⊥ₑ h3} \n   {assume h3; refine h2 h3}}\nend;\n\nopaque symbol ⇔⊥ x :\n  π ((x ⇔ ⊥) = ¬ x) ≔\nbegin\n  assume x;\n  refine propExt (x ⇔ ⊥) (¬ x) _ _\n  {assume h1;\n   refine ∧ₑ₁ h1}\n  {assume h2;\n   refine ∧ᵢ _ _\n   {assume h3; refine h2 h3}\n   {assume h3; refine ⊥ₑ h3}}\nend;\n\nopaque symbol ⇔_idem x :\n  π ((x ⇔ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (x ⇔ x) ⊤ _ _\n  {assume h1; refine ⊤ᵢ}\n  {assume h2;\n   refine ∧ᵢ _ _\n   {assume h3; refine h3}\n   {assume h3; refine h3}}\nend;\n\n\n// Simplifications on Quantifiers\n\nsymbol ∀_const (t : Set) (p : τ o) : π ((`∀ (x : τ t), p) = p)≔\nbegin\n    assume t p;\n    refine propExt (`∀ x, p) p _ _\n        {assume h; refine h (el t)}\n        {assume h a; refine h}\nend;\n\nsymbol ∃_const (t : Set) (p : τ o) : π ((`∃ (x : τ t), p) = p)≔\nbegin\n    assume t p;\n    refine propExt (`∃ x, p) p _ _\n        {assume h; \n         have p_holds : Π (x : τ t), π p → π p\n          {assume x h2; refine h2};\n         refine ∃ₑ [t] [λ y, p] h p_holds}\n        {assume h; \n         have p_holds : π ((λ x , p) (el t))\n          {refine h};\n         refine ∃ᵢ [t] [λ y, p] (el t) p_holds}\nend;\n\n\n// Simplifications reflecting Classical Principles\n\nopaque symbol em_eq_l x :\n  π ((¬ x ∨ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (¬ x ∨ x) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h1;\n     have em_sym: π(¬ x ∨ x)\n       {refine ∨ₑ (em x) _ _\n         {assume h3; refine ∨ᵢ₂ h3}\n         {assume h3; refine ∨ᵢ₁ h3}};\n     refine em_sym}\nend;\n\nopaque symbol em_eq_r x :\n  π ((x ∨ ¬ x) = ⊤) ≔\nbegin\n  assume x;\n  refine propExt (x ∨ ¬ x) ⊤ _ _\n    {assume h1; refine ⊤ᵢ}\n    {assume h1;\n    refine em x}\nend;\n\nopaque symbol ¬¬ₑ_eq x :\n  π (¬ ¬ x = x) ≔\nbegin\n  assume x;\n  refine propExt (¬ ¬ x) x _ _\n    {assume h1; refine dne x h1}\n    {assume h1 h2; refine h2 h1}\nend;\n\n\n/******************************************************************************\n *  Polarity switch       \n ******************************************************************************/\n\nopaque symbol polSwitch x y : π ((¬ x = ¬ y) = (x = y))≔\nbegin\n  assume x y;\n  refine propExt (¬ x = ¬ y) (x = y) _ _\n    {assume h0;\n    have ¬¬x=y : π (¬ ¬ x = y)\n      {refine (ind_eq h0 (λ z, ¬ z = y)) (¬¬ₑ_eq y)};\n    have ¬¬x=y_imp_x=y : π ((¬ ¬ x = y) ⇒ (x = y))\n      {rewrite ¬¬ₑ_eq;\n      assume h1; refine h1};\n    refine ¬¬x=y_imp_x=y ¬¬x=y}\n    {assume h0;\n    refine (ind_eq h0 (λ z, ¬ z = ¬ y)) (eq_refl (¬ y))}\nend;\n\n/******************************************************************************\n *  Setup for the tactics         \n ******************************************************************************/\n\nconstant symbol Tactic : TYPE;\nsymbol tactic : Set;\nrule τ tactic ↪ Tactic;\n\nsymbol #rewrite : Π [a], π a → τ tactic;\nbuiltin \"rewrite\" ≔ #rewrite;\n\nconstant symbol String : TYPE;\nbuiltin \"String\" ≔ String;\n\nsymbol #orelse : Tactic → Tactic → Tactic;\nbuiltin \"orelse\" ≔ #orelse;\nnotation #orelse infix left 10000;\n\nsymbol #refine : Π [a], π a → Tactic;\nbuiltin \"refine\" ≔ #refine;\n\nsymbol #repeat : Tactic → Tactic;\nbuiltin \"repeat\" ≔ #repeat;\n\nsymbol #fail : Tactic;\nbuiltin \"fail\" ≔ #fail;\n\nsymbol #admit : Tactic;\nbuiltin \"admit\" ≔ #admit;\n\nsymbol #and : Tactic → Tactic → Tactic;\nbuiltin \"and\" ≔ #and;\n\nsymbol #apply : Π [a], π a → Tactic;\nbuiltin \"apply\" ≔ #apply;\n\nsymbol #assume : String → Tactic;\nbuiltin \"assume\" ≔ #assume;\n\nsymbol #generalize : Π [a], π a → Tactic;\nbuiltin \"generalize\" ≔ #generalize;\n\nsymbol #have : String → Π [a], π a → Tactic;\nbuiltin \"have\" ≔ #have; \n\nsymbol #induction : Tactic;\nbuiltin \"induction\" ≔ #induction; \n\nsymbol #remove : Π [a], π a → Tactic;\nbuiltin \"remove\" ≔ #remove;\n\nsymbol #reflexivity : Tactic;\nbuiltin \"reflexivity\" ≔ #reflexivity;\n\nsymbol #set : String → Π [a], π a → Tactic;\nbuiltin \"set\" ≔ #set;\n\nsymbol #simplify : Tactic;\nbuiltin \"simplify\" ≔ #simplify;\n\nsymbol #solve : Tactic;\nbuiltin \"solve\" ≔ #solve;\n\nsymbol #symmetry : Tactic;\nbuiltin \"symmetry\" ≔ #symmetry;\n\nsymbol #try : Tactic;\nbuiltin \"try\" ≔ #try;\n\nsymbol #why3 : Tactic;\nbuiltin \"why3\" ≔ #why3; \n\n// necessary in order to define the tactics\nsymbol sett : Set;\nrule τ sett ↪ Set;\n\n\n/******************************************************************************\n *  Definition of combined Simplification tactic        \n ******************************************************************************/\n\nsymbol applyAny : \uD835\uDD43 tactic → Tactic;\nrule applyAny ($t0 ⸬ $tl) ↪ $t0 #orelse (applyAny $tl)\nwith applyAny □ ↪ #fail;\n\nsymbol listOfAllSimpRules ≔ ((#rewrite ∨_idem) ⸬ (#rewrite em_eq_l) ⸬ (#rewrite em_eq_r) ⸬ (#rewrite ∨⊤) ⸬ \n    (#rewrite ⊤∨) ⸬ (#rewrite ∨⊥) ⸬ (#rewrite ⊥∨) ⸬ (#rewrite ∧_idem) ⸬ (#rewrite ∧_contra_r) ⸬ (#rewrite ∧_contra_l) ⸬ \n    (#rewrite ∧⊤) ⸬ (#rewrite ⊤∧) ⸬ (#rewrite ∧⊥) ⸬ (#rewrite ⊥∧) ⸬ (#rewrite ⇒⊤) ⸬ (#rewrite ⊥⇒) ⸬ (#rewrite ⊤⇒) ⸬ \n    (#rewrite ⇒⊥) ⸬ (#rewrite ⇒_idem) ⸬ (#rewrite ⇔⊤) ⸬ (#rewrite ⊤⇔) ⸬ (#rewrite ⊥⇔) ⸬ (#rewrite ⇔⊥) ⸬ \n    (#rewrite ⇔_idem) ⸬ (#rewrite ¬⊤) ⸬ (#rewrite ¬⊥) ⸬ (#rewrite ¬¬ₑ_eq) ⸬ (#rewrite eq⊤) ⸬ (#rewrite ⊤eq) ⸬ \n    (#rewrite eq⊥) ⸬ (#rewrite ⊥eq) ⸬ (#rewrite eq_idem) ⸬ (#rewrite ¬eq⊥) ⸬ (#rewrite ¬⊥eq) ⸬ (#rewrite ¬eq⊤) ⸬ \n    (#rewrite ¬⊤eq) ⸬ (#rewrite ¬eq_idem) ⸬ (#rewrite ∀_const) ⸬ (#rewrite ∃_const) ⸬ (#rewrite polSwitch) ⸬ (#refine ⊤ᵢ) ⸬ □);\n\nsymbol applyAllSimplifications ≔ #repeat (applyAny listOfAllSimpRules);"

  val RwRenc = "///////////////////////////////////////////////////////////////////////////////////////\n////////////////////////////// REWRITE RULES OF THE THEORY ////////////////////////////\n///////////////////////////////////////////////////////////////////////////////////////\n\nrule Prf ⊤ ↪ Π r, Prf r → Prf r;\n\nrule Prf ⊥ ↪ Π r, Prf r;\n\nrule Prf (¬ $p) ↪ Prf $p → Π r, Prf r;\n\nrule Prf ($p ∧ $q) ↪ Π r, (Prf $p → Prf $q → Prf r) → Prf r;\n\nrule Prf ($p ∨ $q) ↪ Π r, (Prf $p → Prf r) → (Prf $q → Prf r) → Prf r;\n\nrule Prf ($x ⇒ $y) ↪ Prf $x → Prf $y;\n\nrule Prf (∀ $p) ↪ Π x, Prf ($p x);\n\nrule Prf (∃ $p) ↪ Π r, (Π x, Prf ($p x) → Prf r) → Prf r;\n\nrule Prf ($x = $y) ↪  Π p , (Prf(p $x) → Prf(p $y));"


}
